import fs from 'node:fs';
import path from 'node:path';
import crypto from 'node:crypto';

export const DEFAULT_DATA_PATH = path.resolve(process.cwd(), 'books.json');

export class BookStore {
  constructor(filePath = DEFAULT_DATA_PATH) {
    this.filePath = filePath;
    this._ensureFile();
  }

  _ensureFile() {
    const dir = path.dirname(this.filePath);
    if (!fs.existsSync(dir)) {
      fs.mkdirSync(dir, { recursive: true });
    }
    if (!fs.existsSync(this.filePath)) {
      fs.writeFileSync(this.filePath, JSON.stringify([], null, 2), 'utf8');
    }
  }

  _readAll() {
    this._ensureFile();
    try {
      const raw = fs.readFileSync(this.filePath, 'utf8');
      const parsed = JSON.parse(raw);
      return Array.isArray(parsed) ? parsed : [];
    } catch {
      return [];
    }
  }

  _writeAll(books) {
    const dir = path.dirname(this.filePath);
    if (!fs.existsSync(dir)) {
      fs.mkdirSync(dir, { recursive: true });
    }
    const tempPath = `${this.filePath}.tmp-${process.pid}-${Date.now()}`;
    fs.writeFileSync(tempPath, JSON.stringify(books, null, 2), 'utf8');
    fs.renameSync(tempPath, this.filePath);
  }

  getAll() {
    return this._readAll();
  }

  getById(id) {
    const books = this._readAll();
    return books.find((b) => b.id === id) || null;
  }

  addBook({ title, author, notes = '', status = 'reading' }) {
    const cleanTitle = typeof title === 'string' ? title.trim() : '';
    const cleanAuthor = typeof author === 'string' ? author.trim() : '';
    const cleanNotes = typeof notes === 'string' ? notes.trim() : '';
    const validStatus = status === 'finished' ? 'finished' : 'reading';

    if (!cleanTitle) {
      const err = new Error('Title is required');
      err.statusCode = 400;
      throw err;
    }
    if (!cleanAuthor) {
      const err = new Error('Author is required');
      err.statusCode = 400;
      throw err;
    }

    const books = this._readAll();
    const now = new Date().toISOString();
    const book = {
      id: crypto.randomUUID(),
      title: cleanTitle,
      author: cleanAuthor,
      notes: cleanNotes,
      status: validStatus,
      createdAt: now,
      finishedAt: validStatus === 'finished' ? now : null,
    };

    books.push(book);
    this._writeAll(books);
    return book;
  }

  updateBook(id, updates = {}) {
    const books = this._readAll();
    const index = books.findIndex((b) => b.id === id);
    if (index === -1) {
      return null;
    }

    const existing = books[index];
    const updated = { ...existing };

    if (updates.title !== undefined) {
      const cleanTitle = typeof updates.title === 'string' ? updates.title.trim() : '';
      if (!cleanTitle) {
        const err = new Error('Title cannot be empty');
        err.statusCode = 400;
        throw err;
      }
      updated.title = cleanTitle;
    }

    if (updates.author !== undefined) {
      const cleanAuthor = typeof updates.author === 'string' ? updates.author.trim() : '';
      if (!cleanAuthor) {
        const err = new Error('Author cannot be empty');
        err.statusCode = 400;
        throw err;
      }
      updated.author = cleanAuthor;
    }

    if (updates.notes !== undefined) {
      updated.notes = typeof updates.notes === 'string' ? updates.notes.trim() : '';
    }

    if (updates.status !== undefined) {
      if (updates.status !== 'reading' && updates.status !== 'finished') {
        const err = new Error('Status must be "reading" or "finished"');
        err.statusCode = 400;
        throw err;
      }
      updated.status = updates.status;
      if (updates.status === 'finished' && !existing.finishedAt) {
        updated.finishedAt = new Date().toISOString();
      } else if (updates.status === 'reading') {
        updated.finishedAt = null;
      }
    }

    books[index] = updated;
    this._writeAll(books);
    return updated;
  }

  markFinished(id) {
    return this.updateBook(id, { status: 'finished' });
  }

  deleteBook(id) {
    const books = this._readAll();
    const index = books.findIndex((b) => b.id === id);
    if (index === -1) {
      return false;
    }
    books.splice(index, 1);
    this._writeAll(books);
    return true;
  }
}

