import http from 'node:http';
import { URL } from 'node:url';
import { BookStore, DEFAULT_DATA_PATH } from './store.js';

export function escapeHtml(str) {
  if (!str) return '';
  return String(str)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#39;');
}

function renderStyles() {
  return `
    :root {
      --bg: #faf8f5;
      --surface: #ffffff;
      --border: #e5e0d8;
      --text: #2c2623;
      --muted: #6e655f;
      --accent: #3d5a45;
      --accent-hover: #2f4736;
      --badge-reading-bg: #eef5f0;
      --badge-reading-text: #2f5238;
      --badge-finished-bg: #f3efe6;
      --badge-finished-text: #5c5243;
      --danger: #a63a3a;
    }
    * { box-sizing: border-box; }
    body {
      margin: 0;
      font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Georgia, sans-serif;
      background: var(--bg);
      color: var(--text);
      line-height: 1.5;
    }
    .container {
      max-width: 780px;
      margin: 0 auto;
      padding: 2rem 1.25rem 4rem;
    }
    header {
      display: flex;
      align-items: baseline;
      justify-content: space-between;
      border-bottom: 1px solid var(--border);
      padding-bottom: 1rem;
      margin-bottom: 2rem;
    }
    header h1 {
      margin: 0;
      font-family: Georgia, serif;
      font-size: 1.75rem;
      font-weight: 700;
    }
    header h1 a {
      color: inherit;
      text-decoration: none;
    }
    header p {
      margin: 0.25rem 0 0;
      color: var(--muted);
      font-size: 0.95rem;
    }
    .card {
      background: var(--surface);
      border: 1px solid var(--border);
      border-radius: 8px;
      padding: 1.25rem 1.5rem;
      margin-bottom: 1.5rem;
      box-shadow: 0 1px 2px rgba(0, 0, 0, 0.03);
    }
    h2 {
      font-family: Georgia, serif;
      font-size: 1.25rem;
      margin: 0 0 1rem 0;
      display: flex;
      align-items: center;
      gap: 0.5rem;
    }
    .count {
      font-family: -apple-system, BlinkMacSystemFont, sans-serif;
      font-size: 0.8rem;
      background: var(--border);
      color: var(--text);
      border-radius: 999px;
      padding: 0.1rem 0.55rem;
      font-weight: 600;
    }
    form .form-row {
      display: grid;
      grid-template-columns: 1fr 1fr;
      gap: 1rem;
      margin-bottom: 1rem;
    }
    @media (max-width: 600px) {
      form .form-row { grid-template-columns: 1fr; }
    }
    label {
      display: block;
      font-size: 0.875rem;
      font-weight: 600;
      margin-bottom: 0.35rem;
    }
    input[type="text"], textarea, select {
      width: 100%;
      padding: 0.6rem 0.75rem;
      border: 1px solid var(--border);
      border-radius: 6px;
      font: inherit;
      background: #fff;
      color: var(--text);
    }
    textarea {
      min-height: 85px;
      resize: vertical;
    }
    input:focus, textarea:focus, select:focus {
      outline: 2px solid var(--accent);
      border-color: transparent;
    }
    .form-actions {
      margin-top: 1rem;
      display: flex;
      justify-content: flex-end;
      gap: 0.75rem;
      align-items: center;
    }
    button, .btn {
      display: inline-flex;
      align-items: center;
      justify-content: center;
      gap: 0.4rem;
      padding: 0.55rem 1rem;
      border-radius: 6px;
      font-size: 0.9rem;
      font-weight: 600;
      cursor: pointer;
      border: 1px solid transparent;
      text-decoration: none;
      transition: background 0.15s ease, border-color 0.15s ease;
    }
    .btn-primary {
      background: var(--accent);
      color: #fff;
    }
    .btn-primary:hover {
      background: var(--accent-hover);
    }
    .btn-secondary {
      background: #fff;
      color: var(--text);
      border-color: var(--border);
    }
    .btn-secondary:hover {
      background: var(--bg);
    }
    .btn-small {
      padding: 0.35rem 0.7rem;
      font-size: 0.82rem;
    }
    .book-list {
      list-style: none;
      padding: 0;
      margin: 0;
      display: flex;
      flex-direction: column;
      gap: 0.75rem;
    }
    .book-item {
      background: var(--surface);
      border: 1px solid var(--border);
      border-radius: 8px;
      padding: 1rem 1.25rem;
      display: flex;
      justify-content: space-between;
      align-items: center;
      gap: 1rem;
    }
    .book-info {
      min-width: 0;
      flex: 1;
    }
    .book-title {
      font-weight: 700;
      font-size: 1.05rem;
      color: var(--text);
      text-decoration: none;
      display: inline-block;
    }
    .book-title:hover {
      color: var(--accent);
      text-decoration: underline;
    }
    .book-author {
      color: var(--muted);
      font-size: 0.92rem;
      margin-top: 0.15rem;
    }
    .book-notes-preview {
      color: var(--muted);
      font-size: 0.85rem;
      margin-top: 0.4rem;
      white-space: nowrap;
      overflow: hidden;
      text-overflow: ellipsis;
    }
    .book-actions {
      display: flex;
      align-items: center;
      gap: 0.5rem;
      flex-shrink: 0;
    }
    .empty-state {
      color: var(--muted);
      font-size: 0.95rem;
      padding: 1rem 0;
      font-style: italic;
    }
    .badge {
      display: inline-block;
      padding: 0.2rem 0.65rem;
      border-radius: 999px;
      font-size: 0.78rem;
      font-weight: 600;
      text-transform: uppercase;
      letter-spacing: 0.03em;
    }
    .badge-reading {
      background: var(--badge-reading-bg);
      color: var(--badge-reading-text);
    }
    .badge-finished {
      background: var(--badge-finished-bg);
      color: var(--badge-finished-text);
    }
    .notes-box {
      background: var(--bg);
      border: 1px solid var(--border);
      border-radius: 6px;
      padding: 1rem;
      white-space: pre-wrap;
      margin-top: 0.5rem;
      min-height: 60px;
    }
    .share-bar {
      display: flex;
      align-items: center;
      gap: 0.5rem;
      margin-top: 1.25rem;
      padding-top: 1rem;
      border-top: 1px solid var(--border);
    }
    .share-input {
      flex: 1;
      font-size: 0.85rem;
      color: var(--muted);
      background: var(--bg);
    }
    .status-msg {
      font-size: 0.85rem;
      color: var(--accent);
      margin-left: 0.5rem;
    }
    .section-block {
      margin-bottom: 2.25rem;
    }
  `;
}

function renderHomePage(books) {
  const reading = books.filter((b) => b.status === 'reading');
  const finished = books.filter((b) => b.status === 'finished');

  const renderBookItem = (b) => `
    <li class="book-item" data-book-id="${escapeHtml(b.id)}" data-status="${escapeHtml(b.status)}">
      <div class="book-info">
        <a class="book-title" href="/books/${ encodeURIComponent(b.id) }">${escapeHtml(b.title)}</a>
        <div class="book-author">by ${escapeHtml(b.author)}</div>
        ${b.notes ? `<div class="book-notes-preview">${escapeHtml(b.notes)}</div>` : ''}
      </div>
      <div class="book-actions">
        ${
          b.status === 'reading'
            ? `<form method="POST" action="/books/${encodeURIComponent(b.id)}/finish" class="finish-form" data-book-id="${escapeHtml(b.id)}" style="margin:0;">
                <button type="submit" class="btn btn-secondary btn-small finish-btn" data-book-id="${escapeHtml(b.id)}">Mark as Finished</button>
              </form>`
            : `<span class="badge badge-finished">Finished</span>`
        }
        <a class="btn btn-secondary btn-small" href="/books/${encodeURIComponent(b.id)}">View</a>
      </div>
    </li>
  `;

  return `<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1.0" />
  <title>Reading Tracker</title>
  <style>${renderStyles()}</style>
</head>
<body>
  <div class="container">
    <header>
      <div>
        <h1><a href="/">My Reading List</a></h1>
        <p>Keep track of what you're reading and your book notes.</p>
      </div>
    </header>

    <section class="card" aria-labelledby="add-book-heading">
      <h2 id="add-book-heading">Add a Book</h2>
      <form id="add-book-form" method="POST" action="/books">
        <div class="form-row">
          <div>
            <label for="title">Title</label>
            <input type="text" id="title" name="title" required placeholder="e.g. The Left Hand of Darkness" />
          </div>
          <div>
            <label for="author">Author</label>
            <input type="text" id="author" name="author" required placeholder="e.g. Ursula K. Le Guin" />
          </div>
        </div>
        <div>
          <label for="notes">Notes</label>
          <textarea id="notes" name="notes" placeholder="Thoughts, favorite quotes, or why you picked it up..."></textarea>
        </div>
        <div class="form-actions">
          <button type="submit" class="btn btn-primary">Add Book</button>
        </div>
      </form>
    </section>

    <section class="section-block" id="currently-reading-section" aria-labelledby="reading-heading">
      <h2 id="reading-heading">Currently Reading <span class="count" id="reading-count">${reading.length}</span></h2>
      <ul class="book-list" id="reading-list">
        ${reading.length ? reading.map(renderBookItem).join('') : '<li class="empty-state" id="reading-empty">No books currently being read. Add one above!</li>'}
      </ul>
    </section>

    <section class="section-block" id="finished-section" aria-labelledby="finished-heading">
      <h2 id="finished-heading">Finished <span class="count" id="finished-count">${finished.length}</span></h2>
      <ul class="book-list" id="finished-list">
        ${finished.length ? finished.map(renderBookItem).join('') : '<li class="empty-state" id="finished-empty">No finished books yet.</li>'}
      </ul>
    </section>
  </div>

  <script>
    function escapeHtml(str) {
      if (!str) return '';
      return String(str)
        .replace(/&/g, '&amp;')
        .replace(/</g, '&lt;')
        .replace(/>/g, '&gt;')
        .replace(/"/g, '&quot;')
        .replace(/'/g, '&#39;');
    }

    const addForm = document.getElementById('add-book-form');
    if (addForm) {
      addForm.addEventListener('submit', async (e) => {
        e.preventDefault();
        const formData = new FormData(addForm);
        const payload = {
          title: formData.get('title'),
          author: formData.get('author'),
          notes: formData.get('notes') || ''
        };
        const res = await fetch('/api/books', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify(payload)
        });
        if (res.ok) {
          window.location.reload();
        }
      });
    }

    document.addEventListener('submit', async (e) => {
      const form = e.target.closest('.finish-form');
      if (!form) return;
      e.preventDefault();
      const bookId = form.getAttribute('data-book-id');
      const res = await fetch('/api/books/' + encodeURIComponent(bookId), {
        method: 'PATCH',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ status: 'finished' })
      });
      if (res.ok) {
        window.location.reload();
      }
    });
  </script>
</body>
</html>`;
}

function renderBookDetailPage(book, originUrl) {
  const sharePath = `/books/${encodeURIComponent(book.id)}`;
  const fullShareUrl = originUrl ? `${originUrl}${sharePath}` : sharePath;

  return `<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1.0" />
  <title>${escapeHtml(book.title)} — Reading Tracker</title>
  <style>${renderStyles()}</style>
</head>
<body>
  <div class="container">
    <header>
      <div>
        <h1><a href="/">My Reading List</a></h1>
      </div>
      <a href="/" class="btn btn-secondary btn-small">&larr; Back to all books</a>
    </header>

    <article class="card" data-book-id="${escapeHtml(book.id)}">
      <div style="display:flex; justify-content:space-between; align-items:flex-start; gap:1rem; flex-wrap:wrap;">
        <div>
          <h2 style="font-size:1.6rem; margin-bottom:0.25rem;" id="book-title">${escapeHtml(book.title)}</h2>
          <div class="book-author" style="font-size:1.05rem;" id="book-author">by ${escapeHtml(book.author)}</div>
        </div>
        <div style="display:flex; align-items:center; gap:0.5rem;">
          <span class="badge ${book.status === 'finished' ? 'badge-finished' : 'badge-reading'}" id="book-status-badge">
            ${book.status === 'finished' ? 'Finished' : 'Currently Reading'}
          </span>
          ${
            book.status === 'reading'
              ? `<form method="POST" action="/books/${encodeURIComponent(book.id)}/finish" id="detail-finish-form" style="margin:0;">
                  <button type="submit" class="btn btn-primary btn-small" id="detail-finish-btn">Mark as Finished</button>
                </form>`
              : ''
          }
        </div>
      </div>

      <div style="margin-top:1.5rem;">
        <h3 style="font-size:1rem; margin-bottom:0.4rem;">Notes</h3>
        <div class="notes-box" id="book-notes">${book.notes ? escapeHtml(book.notes) : '<span class="empty-state">No notes added yet.</span>'}</div>
      </div>

      <details style="margin-top:1.25rem;">
        <summary style="cursor:pointer; font-size:0.9rem; font-weight:600; color:var(--accent);">Edit Notes</summary>
        <form method="POST" action="/books/${encodeURIComponent(book.id)}/notes" id="edit-notes-form" style="margin-top:0.75rem;">
          <label for="notes-input">Update your notes</label>
          <textarea id="notes-input" name="notes">${escapeHtml(book.notes)}</textarea>
          <div class="form-actions">
            <button type="submit" class="btn btn-primary btn-small">Save Notes</button>
          </div>
        </form>
      </details>

      <div class="share-bar">
        <label for="share-link" style="margin:0; white-space:nowrap;">Share link:</label>
        <input type="text" id="share-link" class="share-input" readonly value="${escapeHtml(fullShareUrl)}" />
        <button type="button" class="btn btn-secondary btn-small" id="copy-link-btn">Copy Link</button>
        <span id="copy-status" class="status-msg" aria-live="polite"></span>
      </div>
    </article>
  </div>

  <script>
    const shareInput = document.getElementById('share-link');
    if (shareInput && shareInput.value.startsWith('/')) {
      shareInput.value = window.location.origin + shareInput.value;
    }

    const copyBtn = document.getElementById('copy-link-btn');
    const copyStatus = document.getElementById('copy-status');
    if (copyBtn && shareInput) {
      copyBtn.addEventListener('click', async () => {
        try {
          if (navigator.clipboard && navigator.clipboard.writeText) {
            await navigator.clipboard.writeText(shareInput.value);
          } else {
            shareInput.select();
            document.execCommand('copy');
          }
          copyStatus.textContent = 'Copied!';
          setTimeout(() => { copyStatus.textContent = ''; }, 2000);
        } catch {
          shareInput.select();
        }
      });
    }

    const finishForm = document.getElementById('detail-finish-form');
    if (finishForm) {
      finishForm.addEventListener('submit', async (e) => {
        e.preventDefault();
        const res = await fetch('/api/books/${encodeURIComponent(book.id)}', {
          method: 'PATCH',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ status: 'finished' })
        });
        if (res.ok) window.location.reload();
      });
    }

    const notesForm = document.getElementById('edit-notes-form');
    if (notesForm) {
      notesForm.addEventListener('submit', async (e) => {
        e.preventDefault();
        const notes = document.getElementById('notes-input').value;
        const res = await fetch('/api/books/${encodeURIComponent(book.id)}', {
          method: 'PATCH',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ notes })
        });
        if (res.ok) window.location.reload();
      });
    }
  </script>
</body>
</html>`;
}

function renderNotFoundPage() {
  return `<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1.0" />
  <title>Book Not Found — Reading Tracker</title>
  <style>${renderStyles()}</style>
</head>
<body>
  <div class="container">
    <header>
      <h1><a href="/">My Reading List</a></h1>
    </header>
    <div class="card">
      <h2>Book not found</h2>
      <p>We couldn't find the book you were looking for. It may have been removed or the link is invalid.</p>
      <p><a href="/" class="btn btn-primary">Back to Reading List</a></p>
    </div>
  </div>
</body>
</html>`;
}

function parseBody(req) {
  return new Promise((resolve, reject) => {
    let body = '';
    req.on('data', (chunk) => {
      body += chunk.toString();
      if (body.length > 1e6) {
        reject(new Error('Payload too large'));
      }
    });
    req.on('end', () => {
      const contentType = (req.headers['content-type'] || '').split(';')[0].trim();
      if (!body) {
        resolve({});
        return;
      }
      if (contentType === 'application/json') {
        try {
          resolve(JSON.parse(body));
        } catch (err) {
          const parseErr = new Error('Invalid JSON');
          parseErr.statusCode = 400;
          reject(parseErr);
        }
      } else if (contentType === 'application/x-www-form-urlencoded') {
        const params = new URLSearchParams(body);
        const result = {};
        for (const [k, v] of params.entries()) {
          result[k] = v;
        }
        resolve(result);
      } else {
        try {
          resolve(JSON.parse(body));
        } catch {
          resolve({});
        }
      }
    });
    req.on('error', reject);
  });
}

function sendJson(res, statusCode, data) {
  const payload = JSON.stringify(data);
  res.writeHead(statusCode, {
    'Content-Type': 'application/json; charset=utf-8',
    'Content-Length': Buffer.byteLength(payload),
  });
  res.end(payload);
}

function sendHtml(res, statusCode, html) {
  res.writeHead(statusCode, {
    'Content-Type': 'text/html; charset=utf-8',
    'Content-Length': Buffer.byteLength(html),
  });
  res.end(html);
}

function redirect(res, location) {
  res.writeHead(303, { Location: location });
  res.end();
}

export function createApp({ dataFile = DEFAULT_DATA_PATH } = {}) {
  const store = new BookStore(dataFile);

  const server = http.createServer(async (req, res) => {
    try {
      const host = req.headers.host || 'localhost';
      const protocol = req.headers['x-forwarded-proto'] || 'http';
      const origin = `${protocol}://${host}`;
      const url = new URL(req.url || '/', origin);
      const pathname = url.pathname;
      const method = req.method || 'GET';

      // API Routes
      if (pathname === '/api/books' && method === 'GET') {
        const books = store.getAll();
        return sendJson(res, 200, books);
      }

      if (pathname === '/api/books' && method === 'POST') {
        const body = await parseBody(req);
        const book = store.addBook(body);
        return sendJson(res, 201, book);
      }

      const apiBookMatch = pathname.match(/^\/api\/books\/([^/]+)$/);
      if (apiBookMatch) {
        const id = decodeURIComponent(apiBookMatch[1]);
        if (method === 'GET') {
          const book = store.getById(id);
          if (!book) return sendJson(res, 404, { error: 'Book not found' });
          return sendJson(res, 200, book);
        }
        if (method === 'PATCH' || method === 'PUT') {
          const body = await parseBody(req);
          const updated = store.updateBook(id, body);
          if (!updated) return sendJson(res, 404, { error: 'Book not found' });
          return sendJson(res, 200, updated);
        }
        if (method === 'DELETE') {
          const deleted = store.deleteBook(id);
          if (!deleted) return sendJson(res, 404, { error: 'Book not found' });
          return sendJson(res, 204, '');
        }
      }

      const apiFinishMatch = pathname.match(/^\/api\/books\/([^/]+)\/finish$/);
      if (apiFinishMatch && method === 'POST') {
        const id = decodeURIComponent(apiFinishMatch[1]);
        const updated = store.markFinished(id);
        if (!updated) return sendJson(res, 404, { error: 'Book not found' });
        return sendJson(res, 200, updated);
      }

      // HTML & Form Routes
      if (pathname === '/' && method === 'GET') {
        const books = store.getAll();
        return sendHtml(res, 200, renderHomePage(books));
      }

      if (pathname === '/books' && method === 'POST') {
        const body = await parseBody(req);
        store.addBook(body);
        return redirect(res, '/');
      }

      const bookFinishFormMatch = pathname.match(/^\/books\/([^/]+)\/finish$/);
      if (bookFinishFormMatch && method === 'POST') {
        const id = decodeURIComponent(bookFinishFormMatch[1]);
        const updated = store.markFinished(id);
        if (!updated) return sendHtml(res, 404, renderNotFoundPage());
        const referer = req.headers.referer || '/';
        const redirectTarget = referer.includes(`/books/${encodeURIComponent(id)}`) ? `/books/${encodeURIComponent(id)}` : '/';
        return redirect(res, redirectTarget);
      }

      const bookNotesFormMatch = pathname.match(/^\/books\/([^/]+)\/notes$/);
      if (bookNotesFormMatch && method === 'POST') {
        const id = decodeURIComponent(bookNotesFormMatch[1]);
        const body = await parseBody(req);
        const updated = store.updateBook(id, { notes: body.notes ?? '' });
        if (!updated) return sendHtml(res, 404, renderNotFoundPage());
        return redirect(res, `/books/${encodeURIComponent(id)}`);
      }

      const bookDetailMatch = pathname.match(/^\/books\/([^/]+)$/);
      if (bookDetailMatch && method === 'GET') {
        const id = decodeURIComponent(bookDetailMatch[1]);
        const book = store.getById(id);
        if (!book) {
          return sendHtml(res, 404, renderNotFoundPage());
        }
        return sendHtml(res, 200, renderBookDetailPage(book, origin));
      }

      return sendHtml(res, 404, renderNotFoundPage());
    } catch (err) {
      const status = err.statusCode || 500;
      if ((req.url || '').startsWith('/api/')) {
        return sendJson(res, status, { error: err.message || 'Internal Server Error' });
      }
      return sendHtml(res, status, `<!DOCTYPE html><html><body><h1>Error</h1><p>${escapeHtml(err.message)}</p><a href="/">Back</a></body></html>`);
    }
  });

  return { server, store };
}

if (import.meta.url === `file://${process.argv[1]}`) {
  const port = Number(process.env.PORT) || 3000;
  const dataFile = process.env.BOOKS_FILE || DEFAULT_DATA_PATH;
  const { server } = createApp({ dataFile });
  server.listen(port, () => {
    console.log(`Reading tracker running at http://localhost:${port}`);
  });
}

