import { describe, it, expect, beforeEach, afterEach } from 'vitest';
import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import { createApp } from '../src/server.js';
import { BookStore } from '../src/store.js';

describe('Reading Tracker App & JSON Persistence', () => {
  let tmpDir;
  let dataFile;
  let server;
  let baseUrl;

  beforeEach(async () => {
    tmpDir = fs.mkdtempSync(path.join(os.tmpdir(), 'reading-tracker-test-'));
    dataFile = path.join(tmpDir, 'books.json');
    const app = createApp({ dataFile });
    server = app.server;
    await new Promise((resolve) => server.listen(0, '127.0.0.1', resolve));
    const addr = server.address();
    baseUrl = `http://127.0.0.1:${addr.port}`;
  });

  afterEach(async () => {
    if (server && server.listening) {
      await new Promise((resolve) => server.close(resolve));
    }
    fs.rmSync(tmpDir, { recursive: true, force: true });
  });

  it('persists books to a JSON file across store/server restarts', () => {
    const store1 = new BookStore(dataFile);
    const added = store1.addBook({
      title: 'Dune',
      author: 'Frank Herbert',
      notes: 'Fear is the mind-killer.',
    });

    expect(added.id).toBeTruthy();
    expect(added.status).toBe('reading');

    // Simulate restart with a fresh store instance pointing to the same JSON file
    const store2 = new BookStore(dataFile);
    const allBooks = store2.getAll();
    expect(allBooks).toHaveLength(1);
    expect(allBooks[0].title).toBe('Dune');
    expect(allBooks[0].author).toBe('Frank Herbert');
    expect(allBooks[0].notes).toBe('Fear is the mind-killer.');

    store2.markFinished(added.id);

    const store3 = new BookStore(dataFile);
    const finishedBook = store3.getById(added.id);
    expect(finishedBook.status).toBe('finished');
    expect(finishedBook.finishedAt).toBeTruthy();
  });

  it('shows currently reading and finished sections on the home page', async () => {
    await fetch(`${baseUrl}/api/books`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        title: 'Project Hail Mary',
        author: 'Andy Weir',
        notes: 'Great sci-fi adventure',
      }),
    });

    const res2 = await fetch(`${baseUrl}/api/books`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        title: 'Piranesi',
        author: 'Susanna Clarke',
        notes: 'Mysterious halls and statues',
      }),
    });
    const book2 = await res2.json();

    await fetch(`${baseUrl}/api/books/${book2.id}`, {
      method: 'PATCH',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ status: 'finished' }),
    });

    const homeRes = await fetch(`${baseUrl}/`);
    expect(homeRes.status).toBe(200);
    const html = await homeRes.text();

    expect(html).toContain('Currently Reading');
    expect(html).toContain('Finished');
    expect(html).toContain('Project Hail Mary');
    expect(html).toContain('Andy Weir');
    expect(html).toContain('Piranesi');
    expect(html).toContain('Susanna Clarke');
  });

  it('supports adding a book via standard HTML form POST and marking it finished', async () => {
    const formData = new URLSearchParams({
      title: 'The Dispossessed',
      author: 'Ursula K. Le Guin',
      notes: 'Ambiguous utopia',
    });

    const postRes = await fetch(`${baseUrl}/books`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
      body: formData.toString(),
      redirect: 'manual',
    });
    expect(postRes.status).toBe(303);

    const listRes = await fetch(`${baseUrl}/api/books`);
    const books = await listRes.json();
    expect(books).toHaveLength(1);
    const book = books[0];
    expect(book.title).toBe('The Dispossessed');
    expect(book.status).toBe('reading');

    const finishRes = await fetch(`${baseUrl}/books/${book.id}/finish`, {
      method: 'POST',
      redirect: 'manual',
    });
    expect(finishRes.status).toBe(303);

    const updatedRes = await fetch(`${baseUrl}/api/books/${book.id}`);
    const updatedBook = await updatedRes.json();
    expect(updatedBook.status).toBe('finished');
  });

  it('renders a direct shareable link page for a single book with title, author, and notes', async () => {
    const createRes = await fetch(`${baseUrl}/api/books`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        title: 'Hyperion',
        author: 'Dan Simmons',
        notes: 'Canterbury Tales in space.',
      }),
    });
    const book = await createRes.json();

    const detailRes = await fetch(`${baseUrl}/books/${book.id}`);
    expect(detailRes.status).toBe(200);
    const detailHtml = await detailRes.text();

    expect(detailHtml).toContain('Hyperion');
    expect(detailHtml).toContain('Dan Simmons');
    expect(detailHtml).toContain('Canterbury Tales in space.');
    expect(detailHtml).toContain(`/books/${book.id}`);
  });

  it('returns 404 for unknown book links', async () => {
    const res = await fetch(`${baseUrl}/books/non-existent-id`);
    expect(res.status).toBe(404);
  });
});

